success.beforeFullFileContent:
:root {
  --bg: #0b1220;
  --bg2: #0f1a30;
  --card: #ffffff;
  --ink: #0e1729;
  --muted: #5b6b85;
  --line: #e4e9f2;
  --green: #16a34a;
  --green-deep: #15803d;
  --green-soft: #dcfce7;
  --amber: #b45309;
  --radius: 16px;
  --shadow: 0 12px 32px rgba(11, 18, 32, 0.12);
}

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Inter, sans-serif;
  background: linear-gradient(180deg, var(--bg) 0%, var(--bg2) 320px, #eef2f7 320px);
  color: var(--ink);
  min-height: 100vh;
}

.page { min-height: 100vh; }
.hero {
  color: #fff;
  padding: 36px 20px 26px;
}
.hero-inner {
  max-width: 1220px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  flex-wrap: wrap;
}
.title {
  margin: 0;
  font-size: clamp(30px, 4.5vw, 46px);
  letter-spacing: -0.02em;
  font-weight: 800;
}
.subtitle { margin: 8px 0 0; color: #b9c6dc; font-size: 15px; max-width: 560px; }

.mode-switch {
  display: inline-flex;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.16);
  border-radius: 999px;
  padding: 4px;
  gap: 4px;
}
.mode-switch button {
  border: 0;
  border-radius: 999px;
  padding: 10px 18px;
  font-weight: 700;
  font-size: 14px;
  cursor: pointer;
  background: transparent;
  color: #cbd6ea;
}
.mode-switch button.active { background: #fff; color: var(--ink); }

.wrap { max-width: 1220px; margin: 0 auto; padding: 0 20px 48px; display: grid; gap: 16px; }
.card {
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 18px;
  border: 1px solid rgba(14,23,41,0.06);
}

.controls { display: grid; grid-template-columns: 320px 1fr; gap: 20px; }
@media (max-width: 860px) { .controls { grid-template-columns: 1fr; } }

.add-city { position: relative; }
.add-city label, .setting label, .setting .lbl {
  display: block;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  font-weight: 700;
  margin-bottom: 8px;
}
.add-city label strong, .setting strong { color: var(--ink); }
.add-city input {
  width: 100%;
  padding: 12px 14px;
  border-radius: 12px;
  border: 1.5px solid var(--line);
  font-size: 15px;
  outline: none;
}
.add-city input:focus { border-color: var(--green); box-shadow: 0 0 0 3px var(--green-soft); }
.dropdown {
  position: absolute;
  z-index: 30;
  top: calc(100% + 6px);
  left: 0; right: 0;
  margin: 0;
  padding: 6px;
  list-style: none;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 12px;
  box-shadow: var(--shadow);
  max-height: 300px;
  overflow: auto;
}
.dropdown button {
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  padding: 9px 10px;
  border-radius: 9px;
  cursor: pointer;
  display: grid;
}
.dropdown button:hover { background: #f1f5f9; }
.d-name { font-weight: 700; font-size: 14px; }
.d-meta { font-size: 12px; color: var(--muted); }
.dropdown .empty { padding: 10px; color: var(--muted); font-size: 13px; }

.settings { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; align-items: start; }
@media (max-width: 860px) { .settings { grid-template-columns: 1fr; } }
.setting input[type="range"] { width: 100%; accent-color: var(--green); }
.fmt-switch { display: inline-flex; border: 1.5px solid var(--line); border-radius: 999px; padding: 3px; gap: 3px; }
.fmt-switch button { border: 0; background: transparent; padding: 8px 16px; border-radius: 999px; font-weight: 700; cursor: pointer; color: var(--muted); }
.fmt-switch button.active { background: var(--ink); color: #fff; }

.summary .sum-line { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font-size: 15px; }
.dot { width: 12px; height: 12px; border-radius: 50%; background: var(--green); box-shadow: 0 0 0 4px var(--green-soft); }
.dot.off { background: #f59e0b; box-shadow: 0 0 0 4px #fef3c7; }
.ranges { display: inline-flex; gap: 8px; flex-wrap: wrap; }
.badge {
  background: var(--green-soft);
  color: var(--green-deep);
  font-weight: 800;
  font-size: 13px;
  padding: 5px 12px;
  border-radius: 999px;
  border: 1px solid #bbf7d0;
  white-space: nowrap;
}
.ref-note { color: var(--muted); font-size: 13px; }
.warn {
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
  font-weight: 700;
  padding: 12px 14px;
  border-radius: 12px;
}
.warn-inline { color: var(--amber); font-size: 13px; font-weight: 600; }
.base-list { display: grid; gap: 10px; }
.empty-state { color: var(--muted); font-weight: 600; }

/* Desktop grid */
.grid-desktop { padding: 10px; overflow-x: auto; }
.d-row {
  display: grid;
  grid-template-columns: 190px repeat(24, minmax(52px, 1fr)) 36px;
