:root {
  --bg: #0b1220;
  --bg2: #0f1a30;
  --card: #ffffff;
  --ink: #0e1729;
  --muted: #5b6b85;
  --line: #e4e9f2;
  --green: #16a34a;
  --green-deep: #15803d;
  --green-soft: #dcfce7;
  --amber: #b45309;
  --radius: 16px;
  --shadow: 0 12px 32px rgba(11, 18, 32, 0.12);
}

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Inter, sans-serif;
  background: linear-gradient(180deg, var(--bg) 0%, var(--bg2) 320px, #eef2f7 320px);
  color: var(--ink);
  min-height: 100vh;
}

.page { min-height: 100vh; }
.hero {
  color: #fff;
  padding: 36px 20px 26px;
}
.hero-inner {
  max-width: 1220px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  flex-wrap: wrap;
}
.title {
  margin: 0;
  font-size: clamp(30px, 4.5vw, 46px);
  letter-spacing: -0.02em;
  font-weight: 800;
}
.subtitle { margin: 8px 0 0; color: #b9c6dc; font-size: 15px; max-width: 560px; }

.mode-switch {
  display: inline-flex;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.16);
  border-radius: 999px;
  padding: 4px;
